#!/usr/bin/env python3
from pathlib import Path
import sys,json,zlib,base64,hashlib
if len(sys.argv)!=2: raise SystemExit("usage: patch-shishalove-1.1.73-visual-quality-speed.py <plugin-dir>")
root=Path(sys.argv[1])
payload=json.loads(zlib.decompress(base64.b64decode("")))
for rel,spec in payload.items():
 p=root/rel; data=p.read_bytes()
 if hashlib.sha256(data).hexdigest()!=spec["sha"]: raise SystemExit("unexpected 1.1.72 baseline: "+rel)
 lines=data.decode("utf-8").splitlines(keepends=True)
 for i1,i2,new in reversed(spec["ops"]): lines[i1:i2]=new.splitlines(keepends=True)
 p.write_text("".join(lines),encoding="utf-8")
for rel,sha in {"assets/bridge.css":"c2e1584e09b8566ce03aa5a09ea28e3d800f700497b4f3187311986b8cd18db5","assets/customer.js":"bc3d794decaae688ae97ae3a19ff520b9fc71cefa8c332f8aab0d7372818b5d4"}.items():
 if hashlib.sha256((root/rel).read_bytes()).hexdigest()!=sha: raise SystemExit("preservation lock failed: "+rel)
p=(root/"shishalove-app-bridge.php").read_text();m=(root/"assets/merchant.js").read_text()
for token in ["Version: 1.1.73","slb_visual_last_perf_option_173","WHERE id>%d AND dims=%d","view_support","client_original_width","max=1024"]:
 if token not in p+m: raise SystemExit("missing required token: "+token)
print("Bridge 1.1.73 Visual Search quality/speed patch applied")
